SET CONSTRAINTS ALL DEFERRED;

-- Who may write what: the worker cannot name the comment and creates no
-- version or scenario; the API writes the comment; nobody calls the check.
SELECT pg_temp.check(NOT has_column_privilege('twin_worker','twin.ai_proposals','decision_comment','UPDATE'),
  'the worker cannot write a decision comment');
SELECT pg_temp.check(has_column_privilege('twin_api','twin.ai_proposals','decision_comment','UPDATE'),
  'the API writes the decision comment');
SELECT pg_temp.check(NOT has_table_privilege('twin_worker','twin.model_versions','INSERT')
    AND NOT has_table_privilege('twin_worker','twin.scenarios','INSERT'), 'the worker creates no version or scenario');
SELECT pg_temp.check(NOT has_function_privilege('public','twin.check_proposal_effect()','EXECUTE'),
  'PUBLIC cannot call the effect check');

-- Seven proposals on version 1, generated by their jobs: A21, A22, A26, A27
-- edit and ready; A23, A25 scenario and ready; A24 edit, needing input.
SET LOCAL ROLE twin_api;
