  SELECT a, 'org_01M4YDQK00TA00000000000000', 'mdl_01M4YDQK00TA00000000000001', 'mv_01M4YDQK00TA00000000000001', m, 'generating', 'raise a capacity', 'usr_01M4YDQK00TA00000000000001', '{"node":["node_01m4ydqk00ta00000000000001","node_01m4ydqk00ta00000000000002","node_01m4ydqk00ta00000000000003","node_01m4ydqk00ta00000000000004","node_01m4ydqk00ta00000000000005","node_01m4ydqk00ta00000000000006","node_01m4ydqk00ta00000000000007","node_01m4ydqk00ta00000000000008","node_01m4ydqk00ta00000000000009","node_01m4ydqk00ta00000000000010","node_01m4ydqk00ta00000000000011","node_01m4ydqk00ta00000000000012","node_01m4ydqk00ta00000000000013","node_01m4ydqk00ta00000000000014","node_01m4ydqk00ta00000000000015","node_01m4ydqk00ta00000000000016"],"flow":["flow_01m4ydqk00ta00000000000001","flow_01m4ydqk00ta00000000000002","flow_01m4ydqk00ta00000000000003","flow_01m4ydqk00ta00000000000004","flow_01m4ydqk00ta00000000000005","flow_01m4ydqk00ta00000000000006","flow_01m4ydqk00ta00000000000007","flow_01m4ydqk00ta00000000000008","flow_01m4ydqk00ta00000000000009","flow_01m4ydqk00ta00000000000010","flow_01m4ydqk00ta00000000000011","flow_01m4ydqk00ta00000000000012","flow_01m4ydqk00ta00000000000013","flow_01m4ydqk00ta00000000000014","flow_01m4ydqk00ta00000000000015","flow_01m4ydqk00ta00000000000016"],"resource":["resource_01m4ydqk00ta00000000000001","resource_01m4ydqk00ta00000000000002","resource_01m4ydqk00ta00000000000003","resource_01m4ydqk00ta00000000000004","resource_01m4ydqk00ta00000000000005","resource_01m4ydqk00ta00000000000006","resource_01m4ydqk00ta00000000000007","resource_01m4ydqk00ta00000000000008","resource_01m4ydqk00ta00000000000009","resource_01m4ydqk00ta00000000000010","resource_01m4ydqk00ta00000000000011","resource_01m4ydqk00ta00000000000012","resource_01m4ydqk00ta00000000000013","resource_01m4ydqk00ta00000000000014","resource_01m4ydqk00ta00000000000015","resource_01m4ydqk00ta00000000000016"]}' FROM (VALUES
