-- D-068: the comment of a decision, 1 to 2000 characters, only on an
-- approved or rejected proposal, written by the decision itself.
SET LOCAL ROLE twin_api;
SELECT pg_temp.must_fail(pg_temp.upd('aip_01M4YDQK00TA00000000000026', s), '23514') FROM unnest(ARRAY[
  $q$decision_comment='before any decision'$q$,
  $q$status='rejected', decided_by='usr_01M4YDQK00TA00000000000001', decision_comment=''$q$,
  $q$status='rejected', decided_by='usr_01M4YDQK00TA00000000000001', decision_comment=repeat('x', 2001)$q$
]) AS s;
