  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000026';
SELECT pg_temp.check(decision_comment = repeat('é', 2000) AND decided_at = now(), 'the rejection keeps its 2000-character comment')
  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000026';
SELECT pg_temp.must_fail(pg_temp.upd('aip_01M4YDQK00TA00000000000026', s), '55000') FROM unnest(ARRAY[
  $q$decision_comment='rewritten'$q$,
  $q$decision_comment=NULL$q$
]) AS s;
