SELECT pg_temp.must_fail(pg_temp.upd('aip_01M4YDQK00TA00000000000022', $q$status='conflicted'$q$), '23514');
SELECT pg_temp.must_fail(pg_temp.upd('aip_01M4YDQK00TA00000000000022', $q$status='conflicted', decided_by='usr_01M4YDQK00TA00000000000002'$q$), '42501');
SELECT pg_temp.must_fail(pg_temp.upd('aip_01M4YDQK00TA00000000000022', $q$status='conflicted', decided_by='usr_01M4YDQK00TA00000000000001', decision_comment='x'$q$), '23514');
