  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000022';
SELECT pg_temp.must_fail(pg_temp.upd('aip_01M4YDQK00TA00000000000022', $q$status='rejected'$q$), '55000');

-- A version that names a source proposal is that approved edit
-- proposal's one effect, the next version after its base.
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- the proposal is still ready
  pg_temp.version('mv_01M4YDQK00TA00000000000003', 2, 'mv_01M4YDQK00TA00000000000001', 'aip_01M4YDQK00TA00000000000021')
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- a scenario proposal's effect is never a version
  pg_temp.version('mv_01M4YDQK00TA00000000000003', 2, 'mv_01M4YDQK00TA00000000000001', 'aip_01M4YDQK00TA00000000000023')
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- not the next number after the base
  pg_temp.version('mv_01M4YDQK00TA00000000000003', 3, 'mv_01M4YDQK00TA00000000000001', 'aip_01M4YDQK00TA00000000000021'),
  pg_temp.upd('aip_01M4YDQK00TA00000000000021', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', new_version_id='mv_01M4YDQK00TA00000000000003'$q$)
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- the base moved (another version was published) and the approval
  -- builds on the newer version instead: its parent is not the base
  pg_temp.version('mv_01M4YDQK00TA00000000000004', 2, 'mv_01M4YDQK00TA00000000000001', NULL),
  pg_temp.version('mv_01M4YDQK00TA00000000000003', 3, 'mv_01M4YDQK00TA00000000000004', 'aip_01M4YDQK00TA00000000000021'),
  pg_temp.upd('aip_01M4YDQK00TA00000000000021', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', new_version_id='mv_01M4YDQK00TA00000000000003'$q$)
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- a version without a parent
  pg_temp.version('mv_01M4YDQK00TA00000000000003', 2, NULL, 'aip_01M4YDQK00TA00000000000021'),
  pg_temp.upd('aip_01M4YDQK00TA00000000000021', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', new_version_id='mv_01M4YDQK00TA00000000000003'$q$)
], '23514');
-- The approval: the next version after the base, with the proposal
-- approved for it in the same transaction, and the comment.
