  FROM twin.ai_proposals WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000021';
-- One effect: a second version from the same proposal is refused...
SELECT pg_temp.must_fail(pg_temp.version('mv_01M4YDQK00TA00000000000005', 3, 'mv_01M4YDQK00TA00000000000003', 'aip_01M4YDQK00TA00000000000021'), '23505');
-- ...and another proposal on the old base cannot commit an approval: the
-- next number after its base is taken, and any other is refused at commit
-- (no fork, no silent rebase).
SELECT pg_temp.must_fail(pg_temp.version('mv_01M4YDQK00TA00000000000005', 2, 'mv_01M4YDQK00TA00000000000001', 'aip_01M4YDQK00TA00000000000027'), '23505');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  pg_temp.version('mv_01M4YDQK00TA00000000000005', 3, 'mv_01M4YDQK00TA00000000000001', 'aip_01M4YDQK00TA00000000000027'),
  pg_temp.upd('aip_01M4YDQK00TA00000000000027', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', new_version_id='mv_01M4YDQK00TA00000000000005'$q$)
], '23514');
-- The schema owner is held to the same.
SET LOCAL ROLE twin_owner;
SELECT pg_temp.must_fail_at_commit(ARRAY[
  pg_temp.version('mv_01M4YDQK00TA00000000000005', 3, 'mv_01M4YDQK00TA00000000000003', 'aip_01M4YDQK00TA00000000000027')
], '23514');
SET LOCAL ROLE twin_api;

-- A scenario that names a source proposal is that approved scenario
-- proposal's one effect, with its base, patch and patch hash.
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- the proposal is still ready
  pg_temp.scenario('scn_01M4YDQK00TA00000000000001', '[{"op":"test","path":"/name","value":"Model A v1"}]', 'sha256:1111111111111111111111111111111111111111111111111111111111111111', 'aip_01M4YDQK00TA00000000000025')
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- an edit proposal's effect is never a scenario
  pg_temp.scenario('scn_01M4YDQK00TA00000000000001', '[{"op":"test","path":"/name","value":"Model A v1"}]', 'sha256:1111111111111111111111111111111111111111111111111111111111111111', 'aip_01M4YDQK00TA00000000000027')
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- another patch than the one reviewed
  pg_temp.scenario('scn_01M4YDQK00TA00000000000001', '[{"op":"test","path":"/name","value":"Model A v2"}]', 'sha256:1111111111111111111111111111111111111111111111111111111111111111', 'aip_01M4YDQK00TA00000000000025'),
  pg_temp.upd('aip_01M4YDQK00TA00000000000025', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', scenario_id='scn_01M4YDQK00TA00000000000001'$q$)
], '23514');
SELECT pg_temp.must_fail_at_commit(ARRAY[
  -- another hash than the one reviewed
  pg_temp.scenario('scn_01M4YDQK00TA00000000000001', '[{"op":"test","path":"/name","value":"Model A v1"}]', 'sha256:2222222222222222222222222222222222222222222222222222222222222222', 'aip_01M4YDQK00TA00000000000025'),
  pg_temp.upd('aip_01M4YDQK00TA00000000000025', $q$status='approved', decided_by='usr_01M4YDQK00TA00000000000001', scenario_id='scn_01M4YDQK00TA00000000000001'$q$)
], '23514');
SELECT pg_temp.scenario('scn_01M4YDQK00TA00000000000002', '[{"op":"test","path":"/name","value":"Model A v1"}]', 'sha256:1111111111111111111111111111111111111111111111111111111111111111', 'aip_01M4YDQK00TA00000000000023') \gexec
UPDATE twin.ai_proposals SET status='approved', decided_by='usr_01M4YDQK00TA00000000000001', scenario_id='scn_01M4YDQK00TA00000000000002'
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='aip_01M4YDQK00TA00000000000023';
SET CONSTRAINTS ALL IMMEDIATE; -- the approved proposal's own scenario
SET CONSTRAINTS ALL DEFERRED;
SELECT pg_temp.check(count(*) = 2, 'a scenario approval adds no version') FROM twin.model_versions
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND model_id='mdl_01M4YDQK00TA00000000000001';
SELECT pg_temp.must_fail(pg_temp.scenario('scn_01M4YDQK00TA00000000000003', '[{"op":"test","path":"/name","value":"Model A v1"}]', 'sha256:1111111111111111111111111111111111111111111111111111111111111111', 'aip_01M4YDQK00TA00000000000023'), '23505');
ROLLBACK;
